<?php
namespace Tests\Feature;
use App\Enums\ApprovalStage;use App\Models\PayrollPeriod;use App\Models\PayrollSheet;use App\Models\Project;use App\Models\RoleAssignment;use App\Models\User;use App\Services\Otp\OtpSender;use App\Services\Payroll\ApprovalService;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class OtpApprovalTest extends TestCase { use RefreshDatabase;
 public function test_project_manager_approval_is_bound_to_snapshot(): void {$fake=new class implements OtpSender {public string $code='';public function send(string $mobile,string $code,string $template):?string{$this->code=$code;return 'fake-message';}};$this->app->instance(OtpSender::class,$fake);$p=Project::create(['code'=>'P','name'=>'پروژه']);$u=User::create(['name'=>'مدیر پروژه','mobile'=>'09124444444']);RoleAssignment::create(['user_id'=>$u->id,'role_code'=>'project_manager','project_id'=>$p->id,'started_at'=>now()]);$period=PayrollPeriod::create(['year'=>1405,'month'=>6,'title'=>'شهریور','edit_deadline_at'=>now()->addDay(),'business_timezone'=>'Asia/Tehran']);$sheet=PayrollSheet::create(['period_id'=>$period->id,'project_id'=>$p->id,'project_name_snapshot'=>$p->name]);$this->actingAs($u);$svc=app(ApprovalService::class);$challenge=$svc->request($u->fresh(),$sheet,ApprovalStage::ProjectManager);$approval=$svc->confirm($u->fresh(),$challenge,$fake->code,ApprovalStage::ProjectManager);$this->assertSame($challenge->snapshot_id,$approval->snapshot_id);$this->assertSame('project_team',$sheet->fresh()->edit_barrier->value);}
}
